<?php require_once __DIR__.'/../includes/bootstrap.php'; $u=require_auth();$q=trim((string)($_GET['q']??''));$pdo=db();$stats=$pdo->prepare('SELECT COUNT(*) links, COALESCE(SUM(click_count),0) clicks FROM short_links WHERE user_id=?');$stats->execute([$u['id']]);$stats=$stats->fetch();$sql='SELECT * FROM short_links WHERE user_id=?';$args=[$u['id']];if($q!==''){$sql.=' AND (code LIKE ? OR destination_url LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}$sql.=' ORDER BY created_at DESC LIMIT 50';$s=$pdo->prepare($sql);$s->execute($args);$links=$s->fetchAll();$pageTitle='Dashboard — LinkForge';require __DIR__.'/../includes/header.php'; ?>
<main class="container dashboard"><div class="dash-head"><div><p class="eyebrow">YOUR WORKSPACE</p><h1>Good to see you.</h1></div><a class="button" href="#new-link">New link <span>→</span></a></div><section class="stats"><article><span>Total links</span><strong><?=e((string)$stats['links'])?></strong></article><article><span>Total clicks</span><strong><?=e((string)$stats['clicks'])?></strong></article></section><section id="new-link" class="panel"><h2>Create a short link</h2><form class="dashboard-form" method="post" action="create-link.php"><?=csrf_field()?><label>Destination URL<input name="destination_url" type="url" required placeholder="https://example.com/campaign"></label><label>Alias <small>optional</small><input name="alias" maxlength="64" pattern="[A-Za-z0-9_-]{3,64}" placeholder="launch"></label><label>Expiration <small>optional</small><input name="expires_at" type="datetime-local"></label><button class="button">Create</button></form></section><section class="links-section"><div class="section-top"><h2>Your links</h2><form method="get"><label class="sr-only" for="search">Search links</label><input id="search" name="q" value="<?=e($q)?>" placeholder="Search links"><button class="button secondary">Search</button></form></div><?php if(!$links): ?><p class="empty">No links found. Create your first one above.</p><?php else: ?><div class="link-list"><?php foreach($links as $link): ?><article class="link-row"><div><a class="short-link" href="<?=e(short_url($link['code']))?>" target="_blank" rel="noopener"><?=e(short_url($link['code']))?></a><p title="<?=e($link['destination_url'])?>"><?=e($link['destination_url'])?></p></div><div class="link-meta"><span><?=e((string)$link['click_count'])?> clicks</span><span class="badge <?=$link['is_active']?'':'muted'?>"><?=$link['is_active']?'Active':'Disabled'?></span></div><div class="row-actions"><button class="icon-button copy-button" data-copy="<?=e(short_url($link['code']))?>">Copy</button><a class="icon-button" href="analytics.php?id=<?=$link['id']?>">Analytics</a><form method="post" action="link-action.php" class="inline confirm-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$link['id']?>"><input type="hidden" name="action" value="<?=$link['is_active']?'disable':'enable'?>"><button class="icon-button"><?=$link['is_active']?'Disable':'Enable'?></button></form><form method="post" action="link-action.php" class="inline confirm-form" data-confirm="Delete this link permanently?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$link['id']?>"><input type="hidden" name="action" value="delete"><button class="icon-button danger">Delete</button></form></div></article><?php endforeach ?></div><?php endif ?></section></main><?php require __DIR__.'/../includes/footer.php'; ?>
